.insight {{ background: #eff6ff; border-left: 4px solid #3b82f6; padding: 14px 18px; border-radius: 0 8px 8px 0; margin: 16px 0; font-size: 0.92rem; color: #1e40af; }}
.insight strong {{ display: block; margin-bottom: 4px; }}
