.rec .data-pt {{ font-size: 0.82rem; color: #64748b; margin-top: 4px; }}
.footer {{ text-align: center; padding: 20px; color: #94a3b8; font-size: 0.82rem; }}
.correlation-indicator {{ display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }}
.corr-neg {{ color: #dc2626; }}
.corr-pos {{ color: #16a34a; }}
.corr-neutral {{ color: #64748b; }}
.scatter-container {{ max-height: 380px; }}
@media (max-width: 768px) {{ .chart-row {{ grid-template-columns: 1fr; }} }}
</style>
