import csv
import json
import math
import re
from collections import Counter, defaultdict

# ── 1. Load & Clean Data ──────────────────────────────────────────────────────

def clean_price(val):
    """Remove ₹ symbol and commas, convert to float."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace('₹', '').replace(',', '').strip()
    try:
        return float(val)
    except ValueError:
        return None

def clean_discount(val):
    """Remove % symbol, convert to float."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace('%', '').strip()
    try:
        return float(val)
    except ValueError:
        return None

def clean_rating(val):
    """Convert rating to float, handle malformed entries."""
    if val is None or val == '':
        return None
    try:
        r = float(val)
        if 1.0 <= r <= 5.0:
            return r
        return None
    except (ValueError, TypeError):
        return None

def clean_rating_count(val):
    """Remove commas, convert to int."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace(',', '').strip()
    try:
        return int(val)
    except ValueError:
        return None

def top_level_category(cat):
    """Extract top-level category from pipe-delimited hierarchy."""
    if not cat or not isinstance(cat, str):
        return 'Unknown'
    return cat.split('|')[0].strip()

rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        dp = clean_price(r.get('discounted_price', ''))
        ap = clean_price(r.get('actual_price', ''))
        disc = clean_discount(r.get('discount_percentage', ''))
        rating = clean_rating(r.get('rating', ''))
        rc = clean_rating_count(r.get('rating_count', ''))
        cat = r.get('category', '')
        top_cat = top_level_category(cat)
        sub_cats = cat.split('|') if cat else []
        sub_cat_1 = sub_cats[1].strip() if len(sub_cats) > 1 else 'Other'
        sub_cat_2 = sub_cats[2].strip() if len(sub_cats) > 2 else 'Other'

        rows.append({
            'product_id': r.get('product_id', '').strip(),
            'product_name': r.get('product_name', '').strip(),
            'category': cat,
            'top_category': top_cat,
            'sub_category_1': sub_cat_1,
            'sub_category_2': sub_cat_2,
            'discounted_price': dp,
            'actual_price': ap,
            'discount_percentage': disc,
            'rating': rating,
            'rating_count': rc,
            'review_title': r.get('review_title', ''),
            'review_content': r.get('review_content', ''),
        })

total_raw = len(rows)

# Filter to rows with valid numeric data for core analysis
valid = [r for r in rows if r['rating'] is not None and r['discount_percentage'] is not None
         and r['discounted_price'] is not None and r['actual_price'] is not None]

valid_with_rc = [r for r in valid if r['rating_count'] is not None]

print(f"Total rows: {total_raw}")
print(f"Valid rows (rating + discount + prices): {len(valid)}")
print(f"Valid rows with rating_count: {len(valid_with_rc)}")

# ── 2. Compute KPIs ───────────────────────────────────────────────────────────

ratings = [r['rating'] for r in valid]
discounts = [r['discount_percentage'] for r in valid]
rating_counts = [r['rating_count'] for r in valid_with_rc]
actual_prices = [r['actual_price'] for r in valid]
discounted_prices = [r['discounted_price'] for r in valid]

avg_rating = sum(ratings) / len(ratings)
avg_discount = sum(discounts) / len(discounts)
median_rc = sorted(rating_counts)[len(rating_counts) // 2] if rating_counts else 0
high_rating_share = sum(1 for r in ratings if r >= 4.0) / len(ratings) * 100

# Correlation: discount_percentage vs rating
def pearson_corr(xs, ys):
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return 0
    return num / (dx * dy)

corr_discount_rating = pearson_corr(discounts, ratings)
corr_discount_rc = pearson_corr(
    [r['discount_percentage'] for r in valid_with_rc],
    [math.log10(r['rating_count']) for r in valid_with_rc]
)
corr_price_rating = pearson_corr(actual_prices, ratings)
corr_price_discount = pearson_corr(actual_prices, discounts)

# Top-level category aggregation
cat_agg = defaultdict(lambda: {'ratings': [], 'discounts': [], 'rating_counts': [], 'prices': [], 'count': 0})
for r in valid:
    c = r['top_category']
    cat_agg[c]['ratings'].append(r['rating'])
    cat_agg[c]['discounts'].append(r['discount_percentage'])
    cat_agg[c]['prices'].append(r['discounted_price'])
    cat_agg[c]['count'] += 1
    if r['rating_count'] is not None:
        cat_agg[c]['rating_counts'].append(r['rating_count'])

cat_summary = {}
for c, d in cat_agg.items():
    cat_summary[c] = {
        'count': d['count'],
        'avg_rating': sum(d['ratings']) / len(d['ratings']),
        'avg_discount': sum(d['discounts']) / len(d['discounts']),
        'avg_price': sum(d['prices']) / len(d['prices']),
        'median_rating_count': sorted(d['rating_counts'])[len(d['rating_counts']) // 2] if d['rating_counts'] else 0,
        'high_rating_pct': sum(1 for r in d['ratings'] if r >= 4.0) / len(d['ratings']) * 100,
        'total_rating_count': sum(d['rating_counts']),
    }

# Sub-category aggregation (level 1)
sub1_agg = defaultdict(lambda: {'ratings': [], 'discounts': [], 'rating_counts': [], 'count': 0})
for r in valid:
    s = r['sub_category_1']
    sub1_agg[s]['ratings'].append(r['rating'])
    sub1_agg[s]['discounts'].append(r['discount_percentage'])
    sub1_agg[s]['count'] += 1
    if r['rating_count'] is not None:
        sub1_agg[s]['rating_counts'].append(r['rating_count'])

sub1_summary = {}
for s, d in sub1_agg.items():
    sub1_summary[s] = {
        'count': d['count'],
        'avg_rating': sum(d['ratings']) / len(d['ratings']),
        'avg_discount': sum(d['discounts']) / len(d['discounts']),
        'median_rc': sorted(d['rating_counts'])[len(d['rating_counts']) // 2] if d['rating_counts'] else 0,
        'total_rc': sum(d['rating_counts']),
    }

# ── 3. Rating Distribution ────────────────────────────────────────────────────

rating_bins = {'1.0-1.9': 0, '2.0-2.9': 0, '3.0-3.4': 0, '3.5-3.9': 0, '4.0-4.4': 0, '4.5-5.0': 0}
for r in ratings:
    if r < 2.0: rating_bins['1.0-1.9'] += 1
    elif r < 3.0: rating_bins['2.0-2.9'] += 1
    elif r < 3.5: rating_bins['3.0-3.4'] += 1
    elif r < 4.0: rating_bins['3.5-3.9'] += 1
    elif r < 4.5: rating_bins['4.0-4.4'] += 1
    else: rating_bins['4.5-5.0'] += 1

# Discount bins for correlation analysis
discount_bins = {'0-20%': [], '20-40%': [], '40-60%': [], '60-80%': [], '80-100%': []}
for r in valid:
    d = r['discount_percentage']
    if d < 20: discount_bins['0-20%'].append(r['rating'])
    elif d < 40: discount_bins['20-40%'].append(r['rating'])
    elif d < 60: discount_bins['40-60%'].append(r['rating'])
    elif d < 80: discount_bins['60-80%'].append(r['rating'])
    else: discount_bins['80-100%'].append(r['rating'])

discount_bin_avg = {k: (sum(v)/len(v) if v else 0) for k, v in discount_bins.items()}
discount_bin_count = {k: len(v) for k, v in discount_bins.items()}

# Top products by rating_count
top_by_engagement = sorted(valid_with_rc, key=lambda r: r['rating_count'], reverse=True)[:15]

# ── 4. Top/Bottom Categories ─────────────────────────────────────────────────

sorted_cats_by_rating = sorted(cat_summary.items(), key=lambda x: x[1]['avg_rating'], reverse=True)
sorted_cats_by_engagement = sorted(cat_summary.items(), key=lambda x: x[1]['total_rating_count'], reverse=True)

# ── 5. Price Segment Analysis ─────────────────────────────────────────────────

price_bins = {'<₹500': [], '₹500-₹1,000': [], '₹1,000-₹5,000': [], '₹5,000-₹15,000': [], '₹15,000+': []}
for r in valid:
    p = r['discounted_price']
    if p < 500: price_bins['<₹500'].append(r)
    elif p < 1000: price_bins['₹500-₹1,000'].append(r)
    elif p < 5000: price_bins['₹1,000-₹5,000'].append(r)
    elif p < 15000: price_bins['₹5,000-₹15,000'].append(r)
    else: price_bins['₹15,000+'].append(r)

