high_rating_share = sum(1 for r in ratings if r >= 4.0) / len(ratings) * 100

# Correlation: discount_percentage vs rating
def pearson_corr(xs, ys):
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return 0
    return num / (dx * dy)

corr_discount_rating = pearson_corr(discounts, ratings)
corr_discount_rc = pearson_corr(
    [r['discount_percentage'] for r in valid_with_rc],
    [math.log10(r['rating_count']) for r in valid_with_rc]
)
corr_price_rating = pearson_corr(actual_prices, ratings)
corr_price_discount = pearson_corr(actual_prices, discounts)

