# Simple keyword-based sentiment from review_content
positive_words = ['good', 'great', 'excellent', 'best', 'awesome', 'amazing', 'love', 'worth', 'nice',
                  'fast', 'quality', 'perfect', 'happy', 'satisfied', 'recommend', 'superb', 'wonderful',
                  'outstanding', 'fantastic', 'brilliant', 'durable', 'sturdy', 'value', 'better',
                  'impressive', 'fine', 'beautiful', 'well', 'liked', 'pleased', 'working', 'works',
                  'flawlessly', 'seamless', 'easy', 'smooth']
negative_words = ['bad', 'poor', 'worst', 'terrible', 'waste', 'useless', 'broke', 'broken',
                  'defective', 'disappointed', 'issue', 'problem', 'slow', 'cheap', 'not',
                  'failure', 'failed', 'lag', 'lags', 'lagging', 'stuck', 'freeze', 'stopped',
                  'damaged', 'return', 'refund', 'garbage', 'pathetic', 'horrible', 'awful',
                  'faulty', 'complaint', 'doesn\'t', 'doesnt', 'never', 'cannot', "won't",
                  'overheat', 'overheating', 'disconnect', 'disconnects', 'no']

def count_sentiment(text):
    if not text:
        return 0, 0
    text_lower = text.lower()
    pos = sum(1 for w in positive_words if w in text_lower)
    neg = sum(1 for w in negative_words if w in text_lower)
    return pos, neg

total_pos = 0
total_neg = 0
review_count = 0
for r in valid:
    p, n = count_sentiment(r['review_content'])
    total_pos += p
    total_neg += n
    if p + n > 0:
