def clean_price(val):
    """Remove ₹ symbol and commas, convert to float."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace('₹', '').replace(',', '').strip()
    try:
        return float(val)
    except ValueError:
        return None

def clean_discount(val):
    """Remove % symbol, convert to float."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace('%', '').strip()
    try:
        return float(val)
    except ValueError:
        return None

def clean_rating(val):
    """Convert rating to float, handle malformed entries."""
    if val is None or val == '':
        return None
    try:
        r = float(val)
        if 1.0 <= r <= 5.0:
            return r
        return None
    except (ValueError, TypeError):
        return None

def clean_rating_count(val):
    """Remove commas, convert to int."""
    if not val or not isinstance(val, str):
        return None
    val = val.replace(',', '').strip()
    try:
        return int(val)
    except ValueError:
        return None

def top_level_category(cat):
    """Extract top-level category from pipe-delimited hierarchy."""
    if not cat or not isinstance(cat, str):
        return 'Unknown'
    return cat.split('|')[0].strip()

rows = []
